package com.nickd342.yippeebluetears;

import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class StreamOrderOverlay extends Overlay
{
    // Height above the tile to draw the number, so it sits on the stream
    // rather than at the base of the wall.
    private static final int TEXT_Z_OFFSET = 150;

    private final Client client;
    private final StreamOrderTracker tracker;
    private final YippeeBlueTearsConfig config;

    @Inject
    StreamOrderOverlay(Client client, StreamOrderTracker tracker, YippeeBlueTearsConfig config)
    {
        this.client = client;
        this.tracker = tracker;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showStreamOrder())
        {
            return null;
        }

        Map<DecorativeObject, TearStream> streams = tracker.getStreams();
        if (streams.isEmpty())
        {
            return null;
        }

        Font font = FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 24f);
        graphics.setFont(font);

        int plane = client.getTopLevelWorldView().getPlane();
        for (Map.Entry<DecorativeObject, TearStream> entry : streams.entrySet())
        {
            DecorativeObject object = entry.getKey();
            if (object.getPlane() != plane)
            {
                continue;
            }

            TearStream stream = entry.getValue();
            String text = String.valueOf(stream.getOrder());
            Point point = Perspective.getCanvasTextLocation(client, graphics, object.getLocalLocation(), text, TEXT_Z_OFFSET);
            if (point != null)
            {
                OverlayUtil.renderTextLocation(graphics, point, text, stream.isBlue() ? config.blueOrderColor() : config.greenOrderColor());
            }
        }

        return null;
    }
}

package com.nickd342.yippeebluetears;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.gameval.ObjectID;

// Works out where each tear stream falls in its world's stream order.
//
// The six streams change in a burst, one game tick apart, followed by a
// pause of around eleven ticks. A world's order (e.g. gggbbb) is the colour
// sequence within a burst, so the first stream after the pause is always the
// first in the order. Blue and green streams are each numbered 1-3 from there.
//
// We only number a burst we saw start. If we arrive (log in, hop, enter the
// cave) partway through one, we can't tell how many streams we missed, so
// those streams are left unnumbered until the next burst begins.
@Slf4j
@Singleton
class StreamOrderTracker
{
    private static final int TOG_REGION = 12948;
    private static final int STREAMS_PER_COLOUR = 3;

    private final Client client;

    // Streams currently on the walls that we've numbered.
    private final Map<DecorativeObject, TearStream> streams = new HashMap<>();

    // Streams numbered in the burst in progress, so they can be un-numbered
    // if the burst turns out to be bad data.
    private final List<DecorativeObject> currentBurst = new ArrayList<>();

    // First tick we were logged in and in the cave, or -1 if we aren't.
    private int watchStartTick = -1;

    // Tick the last stream spawned on, or -1 if none have since watching began.
    private int lastSpawnTick = -1;

    // Whether the burst in progress started while we were watching, so its
    // order is known.
    private boolean numbering;
    private int blueInBurst;
    private int greenInBurst;

    @Inject
    StreamOrderTracker(Client client)
    {
        this.client = client;
    }

    Map<DecorativeObject, TearStream> getStreams()
    {
        return Collections.unmodifiableMap(streams);
    }

    void onGameStateChanged(GameState gameState)
    {
        // Entering or leaving the cave, hopping, and logging out all load a
        // new scene, so we have to wait for a fresh burst.
        if (gameState != GameState.LOGGED_IN)
        {
            reset();
        }
    }

    void onGameTick()
    {
        if (!inCave())
        {
            if (watchStartTick != -1)
            {
                reset();
            }
            return;
        }

        if (watchStartTick == -1)
        {
            watchStartTick = client.getTickCount();
        }
    }

    void onSpawned(DecorativeObject object)
    {
        int id = object.getId();
        boolean blue = isBlueTears(id);
        if (!blue && !isGreenTears(id))
        {
            return;
        }

        // Streams already running when the scene loads are re-sent without
        // us having seen them start.
        if (client.getGameState() != GameState.LOGGED_IN || !inCave())
        {
            return;
        }

        int tick = client.getTickCount();
        if (tick == lastSpawnTick)
        {
            // Bursts spawn one stream per tick. More than one in a tick is
            // the client reloading the scene, not real spawns.
            log.debug("Multiple tear streams spawned on tick {}, discarding burst", tick);
            discardBurst();
            return;
        }

        boolean continuesBurst = lastSpawnTick != -1 && tick == lastSpawnTick + 1;
        if (!continuesBurst)
        {
            // A new burst only has a known start if we saw the quiet gap
            // before it. The first spawn after arriving, without a quiet
            // tick watched first, may be partway through a burst.
            boolean sawGap = lastSpawnTick != -1 || (watchStartTick != -1 && tick - watchStartTick > 1);
            if (sawGap)
            {
                startBurst();
            }
            else
            {
                numbering = false;
            }
        }
        lastSpawnTick = tick;

        if (!numbering)
        {
            return;
        }

        int order = blue ? ++blueInBurst : ++greenInBurst;
        if (order > STREAMS_PER_COLOUR)
        {
            log.debug("More than {} {} streams in one burst, discarding burst", STREAMS_PER_COLOUR, blue ? "blue" : "green");
            discardBurst();
            return;
        }

        streams.put(object, new TearStream(blue, order));
        currentBurst.add(object);
        log.debug("{} tears #{} spawned at {} on tick {}", blue ? "Blue" : "Green", order, object.getWorldLocation(), tick);
    }

    void onDespawned(DecorativeObject object)
    {
        streams.remove(object);
        currentBurst.remove(object);
    }

    void reset()
    {
        streams.clear();
        currentBurst.clear();
        watchStartTick = -1;
        lastSpawnTick = -1;
        numbering = false;
        blueInBurst = 0;
        greenInBurst = 0;
    }

    private void startBurst()
    {
        currentBurst.clear();
        numbering = true;
        blueInBurst = 0;
        greenInBurst = 0;
    }

    private void discardBurst()
    {
        for (DecorativeObject object : currentBurst)
        {
            streams.remove(object);
        }
        currentBurst.clear();
        numbering = false;
    }

    private boolean inCave()
    {
        Player player = client.getLocalPlayer();
        return player != null && player.getWorldLocation().getRegionID() == TOG_REGION;
    }

    private static boolean isBlueTears(int id)
    {
        return id == ObjectID.TOG_WEEPING_WALL_GOOD_R || id == ObjectID.TOG_WEEPING_WALL_GOOD_L;
    }

    private static boolean isGreenTears(int id)
    {
        return id == ObjectID.TOG_WEEPING_WALL_BAD_R || id == ObjectID.TOG_WEEPING_WALL_BAD_L;
    }
}

package com.nickd342.yippeebluetears;

import lombok.Value;

// A tear stream that spawned while the player was in the cave, and where it
// falls in the spawn order for its colour (1-3).
@Value
class TearStream
{
    boolean blue;
    int order;
}

package com.nickd342.yippeebluetears;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("yippee-blue-tears")
public interface YippeeBlueTearsConfig extends Config
{
    @Range(max = 100)
    @Units(Units.PERCENT)
    @ConfigItem(
        keyName = "volume",
        name = "Volume",
        description = "How loud the tear sound plays. Set to 0 to mute it.",
        position = 0
    )
    default int volume()
    {
        return 10;
    }

    @ConfigItem(
        keyName = "showStreamOrder",
        name = "Show stream order",
        description = "Numbers each blue and green tear stream 1-3 in the order it spawned",
        position = 1
    )
    default boolean showStreamOrder()
    {
        return true;
    }

    @ConfigItem(
        keyName = "blueOrderColor",
        name = "Blue number colour",
        description = "Colour of the order numbers drawn on blue tear streams",
        position = 2
    )
    default Color blueOrderColor()
    {
        return Color.CYAN;
    }

    @ConfigItem(
        keyName = "greenOrderColor",
        name = "Green number colour",
        description = "Colour of the order numbers drawn on green tear streams",
        position = 3
    )
    default Color greenOrderColor()
    {
        return Color.GREEN;
    }
}

package com.nickd342.yippeebluetears;

import com.google.inject.Provides;
import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.DecorativeObjectDespawned;
import net.runelite.api.events.DecorativeObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@PluginDescriptor(
    name = "Yippee Blue Tears",
    description = "Plays a rewarding sound everytime a consecutive blue tear stream appears on a wall you're already collecting from",
    tags = {"tears", "guthix", "sound", "yippee"}
)
public class YippeeBlueTearsPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private AudioPlayer audioPlayer;

    @Inject
    private YippeeBlueTearsConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private StreamOrderOverlay streamOrderOverlay;

    @Inject
    private StreamOrderTracker streamOrderTracker;

    // The wall tile the player last clicked to collect from, or null if they
    // haven't clicked one or have since clicked something else in the world.
    private WorldPoint targetWall;

    private static final String COLLECT_OPTION = "Collect-from";

    @Provides
    YippeeBlueTearsConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(YippeeBlueTearsConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(streamOrderOverlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(streamOrderOverlay);
        clearTarget();
        streamOrderTracker.reset();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        streamOrderTracker.onGameStateChanged(event.getGameState());
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        streamOrderTracker.onGameTick();
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        MenuAction action = event.getMenuAction();
        switch (action)
        {
            case GAME_OBJECT_FIRST_OPTION:
            case GAME_OBJECT_SECOND_OPTION:
            case GAME_OBJECT_THIRD_OPTION:
            case GAME_OBJECT_FOURTH_OPTION:
            case GAME_OBJECT_FIFTH_OPTION:
                // The clickable wall isn't necessarily the tears decoration
                // itself, so also accept the option text as a fallback.
                if (isWeepingWall(event.getId()) || COLLECT_OPTION.equalsIgnoreCase(event.getMenuOption()))
                {
                    targetWall = WorldPoint.fromScene(client.getTopLevelWorldView(),
                        event.getParam0(), event.getParam1(), client.getTopLevelWorldView().getPlane());
                    log.debug("Collecting from wall {} (object {})", targetWall, event.getId());
                }
                else
                {
                    clearTarget();
                }
                break;
            case WALK:
            case ITEM_USE_ON_GAME_OBJECT:
            case WIDGET_TARGET_ON_GAME_OBJECT:
            case ITEM_USE_ON_NPC:
            case WIDGET_TARGET_ON_NPC:
            case NPC_FIRST_OPTION:
            case NPC_SECOND_OPTION:
            case NPC_THIRD_OPTION:
            case NPC_FOURTH_OPTION:
            case NPC_FIFTH_OPTION:
            case ITEM_USE_ON_PLAYER:
            case WIDGET_TARGET_ON_PLAYER:
            case PLAYER_FIRST_OPTION:
            case PLAYER_SECOND_OPTION:
            case PLAYER_THIRD_OPTION:
            case PLAYER_FOURTH_OPTION:
            case PLAYER_FIFTH_OPTION:
            case PLAYER_SIXTH_OPTION:
            case PLAYER_SEVENTH_OPTION:
            case PLAYER_EIGHTH_OPTION:
            case ITEM_USE_ON_GROUND_ITEM:
            case WIDGET_TARGET_ON_GROUND_ITEM:
            case GROUND_ITEM_FIRST_OPTION:
            case GROUND_ITEM_SECOND_OPTION:
            case GROUND_ITEM_THIRD_OPTION:
            case GROUND_ITEM_FOURTH_OPTION:
            case GROUND_ITEM_FIFTH_OPTION:
                // Any other world interaction stops the player collecting.
                clearTarget();
                break;
            default:
                break;
        }
    }

    @Subscribe
    public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
    {
        DecorativeObject decorativeObject = event.getDecorativeObject();
        streamOrderTracker.onSpawned(decorativeObject);

        if (targetWall == null)
        {
            return;
        }

        int id = decorativeObject.getId();
        if (!isBlueTears(id))
        {
            return;
        }

        log.debug("Blue tears spawned at {} (collecting from {})", decorativeObject.getWorldLocation(), targetWall);
        if (!targetWall.equals(decorativeObject.getWorldLocation()))
        {
            return;
        }

        // Objects are re-sent while a scene loads; those aren't new streams.
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        Player player = client.getLocalPlayer();
        if (player == null)
        {
            return;
        }

        // The tears object sits on the wall's own tile, next to the player.
        // If the player isn't there yet (still walking over) they aren't
        // collecting, so this stream doesn't count.
        if (targetWall.distanceTo(player.getWorldLocation()) > 1)
        {
            return;
        }

        playSound();
    }

    @Subscribe
    public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
    {
        streamOrderTracker.onDespawned(event.getDecorativeObject());
    }

    private void clearTarget()
    {
        targetWall = null;
    }

    private static boolean isBlueTears(int id)
    {
        return id == ObjectID.TOG_WEEPING_WALL_GOOD_R || id == ObjectID.TOG_WEEPING_WALL_GOOD_L;
    }

    private static boolean isWeepingWall(int id)
    {
        switch (id)
        {
            case ObjectID.TOG_WEEPING_WALL_GOOD_R:
            case ObjectID.TOG_WEEPING_WALL_BAD_R:
            case ObjectID.TOG_WEEPING_WALL_OFF_R:
            case ObjectID.TOG_WEEPING_WALL_GOOD_L:
            case ObjectID.TOG_WEEPING_WALL_BAD_L:
            case ObjectID.TOG_WEEPING_WALL_OFF_L:
            case ObjectID.TOG_WEEPING_WALL_BACK_R:
            case ObjectID.TOG_WEEPING_WALL_BACK_L:
            case ObjectID.TOG_WEEPINGWALL:
                return true;
            default:
                return false;
        }
    }

    private void playSound()
    {
        int volume = config.volume();
        if (volume <= 0)
        {
            return;
        }

        // AudioPlayer's gain is in decibels, not a linear scale, so convert the
        // percentage to an attenuation: 100% is untouched, 50% is -6dB.
        float gain = 20f * (float) Math.log10(volume / 100f);

        // AudioPlayer.play() opens the clip and returns immediately - playback
        // runs on the Java Sound system's own thread, not the client thread.
        try
        {
            audioPlayer.play(YippeeBlueTearsPlugin.class, "/tear.wav", gain);
        }
        catch (Exception e)
        {
            log.warn("Failed to play tear sound", e);
        }
    }
}

package com.nickd342.yippeebluetears;

